import{j as e}from"./index-P0itqdt5.js";import{L as n}from"./LegalLayout-I8xWu3jj.js";import{u as r}from"./react-vendor-B6KbklQe.js";import"./supabase-BH9cnazT.js";import"./icons-C-YSG70s.js";import"./Footer-09Yl6MUp.js";const s=[{title:"Introduction",content:['Welcome to SnapQuote ("Company", "we", "our", or "us"). These Terms & Conditions govern your use of our web application and services accessible at SnapQuote ("Service"). By accessing or using our Service, you agree to be bound by these Terms. If you do not agree with any part of these Terms, you may not use the Service.',"SnapQuote is a SaaS platform designed for photography studios and creative professionals to generate, manage, and share client quotations."]},{title:"Use of Service",content:["SnapQuote grants you a limited, non-exclusive, non-transferable license to access and use the Service for your internal business purposes. This license is conditioned on your compliance with these Terms.","You may not: (a) license, sublicense, sell, resell, or transfer the Service; (b) modify or make derivative works based on the Service; (c) reverse engineer or attempt to extract source code; (d) use the Service to build a competitive product; (e) use the Service for any unlawful purpose or in violation of any applicable laws.","We reserve the right to modify, suspend, or discontinue any part of the Service at any time with reasonable notice."]},{title:"User Responsibilities",content:["You are responsible for maintaining the confidentiality of your account credentials. You are fully responsible for all activities that occur under your account.","You agree to provide accurate, current, and complete information during registration and to keep your account information updated. SnapQuote reserves the right to suspend or terminate accounts with inaccurate or fraudulent information.","You are solely responsible for any content you upload, including client data, studio details, pricing, and any information included in quotations generated through the Service.","You must not use the Service to store or transmit any unlawful, harmful, threatening, abusive, defamatory, or otherwise objectionable content."]},{title:"Subscription & Payments",content:["SnapQuote offers subscription plans on a monthly or annual billing cycle. All plan details, pricing, and feature inclusions are described on our Pricing page and may be updated from time to time with prior notice.","New users are provided a free trial period with a limited number of quotations. No credit card or payment is required during the trial. Upon exhausting your trial allocation or choosing to upgrade, payment will be collected via our payment processor.","All payments are processed securely through Razorpay. By subscribing, you authorise SnapQuote and its payment processors to charge the applicable fees to your selected payment method.","Subscription fees are billed in advance. Failure to complete payment may result in suspension of your account until payment is received. Annual subscriptions are billed as a single upfront payment.","SnapQuote reserves the right to change subscription pricing with at least 30 days prior notice. Price changes will take effect at the start of your next billing period."]},{title:"Intellectual Property",content:["The Service, including all software, designs, text, graphics, and other materials, are the exclusive intellectual property of SnapQuote and are protected by applicable copyright, trademark, and other intellectual property laws.","You retain ownership of all content you create or upload through the Service, including quotations, studio information, and client data. By using the Service, you grant SnapQuote a limited, non-exclusive license to process and store this content solely for the purpose of providing the Service."]},{title:"Limitations of Liability",content:["To the fullest extent permitted by applicable law, SnapQuote and its affiliates, directors, employees, and agents shall not be liable for any indirect, incidental, special, consequential, or punitive damages, including loss of profits, data, or business opportunities, arising from your use of or inability to use the Service.",'SnapQuote does not warrant that the Service will be uninterrupted, error-free, or completely secure. We provide the Service on an "as-is" and "as-available" basis without warranties of any kind, either express or implied.',"Our total liability to you for any claims arising out of or relating to these Terms or the Service shall not exceed the amount paid by you to SnapQuote in the twelve (12) months preceding the claim."]},{title:"Termination",content:["Either party may terminate these Terms at any time. You may terminate by discontinuing use of the Service and deleting your account. SnapQuote may suspend or terminate your access immediately if you violate these Terms, engage in fraudulent activity, or fail to make timely payments.","Upon termination, your right to use the Service ceases immediately. SnapQuote may retain your account data for a reasonable period for legal or operational reasons, after which it may be permanently deleted.","Provisions that by their nature should survive termination — including intellectual property, limitations of liability, and dispute resolution — shall survive."]},{title:"Governing Law",content:["These Terms shall be governed by and construed in accordance with the laws of India, without regard to conflict of law principles. Any disputes arising out of or related to these Terms shall be subject to the exclusive jurisdiction of the courts located in India."]},{title:"Contact Information",content:["If you have any questions, concerns, or requests regarding these Terms & Conditions, please contact us:","Email: contact@snapquote.in","Website: snapquote.in"]}];function h(){const i=r();return e.jsx(n,{title:"Terms & Conditions",lastUpdated:"April 1, 2026",onBack:()=>i(-1),children:s.map(t=>e.jsxs("section",{className:"mb-10",children:[e.jsx("h2",{className:"text-base font-semibold text-slate-900 mb-3",children:t.title}),e.jsx("div",{className:"space-y-3",children:t.content.map((o,a)=>e.jsx("p",{className:"text-sm text-slate-600 leading-relaxed",children:o},a))})]},t.title))})}export{h as TermsAndConditions};
